const readyActionsJob = `-- name: ReadyActionsJob :execrows
UPDATE actions_jobs
SET status = $1, name = $2, matrix = $3, payload = $4, runs_on = $5,
    environment = $6, concurrency_group = $7, concurrency_cancel = $8,
    timeout_minutes = $9, fail_fast = $10, max_parallel = $11, inputs = $12,
    updated_at = now()
WHERE id = $13 AND status = 'blocked'
`

type ReadyActionsJobParams struct {
	Status            string
	Name              string
	Matrix            []byte
	Payload           []byte
	RunsOn            []string
	Environment       string
	ConcurrencyGroup  string
	ConcurrencyCancel bool
	TimeoutMinutes    int32
	FailFast          bool
	MaxParallel       int32
	Inputs            []byte
	ID                uuid.UUID
}

// A blocked job whose needs are met becomes concrete: the evaluated
// matrix combination, runs-on, environment and the single-job payload.
func (q *Queries) ReadyActionsJob(ctx context.Context, arg ReadyActionsJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, readyActionsJob,
		arg.Status,
		arg.Name,
		arg.Matrix,
		arg.Payload,
		arg.RunsOn,
		arg.Environment,
		arg.ConcurrencyGroup,
		arg.ConcurrencyCancel,
		arg.TimeoutMinutes,
		arg.FailFast,
		arg.MaxParallel,
		arg.Inputs,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

