const upsertActionsEnvironment = `-- name: UpsertActionsEnvironment :one

INSERT INTO actions_environments (id, repo_id, name, require_approval, reviewers)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (repo_id, name) DO UPDATE
SET require_approval = EXCLUDED.require_approval, reviewers = EXCLUDED.reviewers, updated_at = now()
RETURNING id, repo_id, name, require_approval, reviewers, created_at, updated_at
`

type UpsertActionsEnvironmentParams struct {
	ID              uuid.UUID
	RepoID          uuid.UUID
	Name            string
	RequireApproval bool
	Reviewers       []uuid.UUID
}

// ---- environments ----
func (q *Queries) UpsertActionsEnvironment(ctx context.Context, arg UpsertActionsEnvironmentParams) (ActionsEnvironment, error) {
	row := q.db.QueryRow(ctx, upsertActionsEnvironment,
		arg.ID,
		arg.RepoID,
		arg.Name,
		arg.RequireApproval,
		arg.Reviewers,
	)
	var i ActionsEnvironment
	err := row.Scan(
		&i.ID,
		&i.RepoID,
		&i.Name,
		&i.RequireApproval,
		&i.Reviewers,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

